#include <iostream>
#include <string>

using namespace std;

int main() {
    string s;
    cin >> s;

    int n = s.length();
    int left = -1, right = -1;

    for (int i = 0; i < n; i++) {
        if (s[i] == '[') {
            left = i;
            break;
        }
    }

    for (int i = n - 1; i >= 0; i--) {
        if (s[i] == ']') {
            right = i;
            break;
        }
    }

    if (left == -1 || right == -1 || left >= right) {
        cout << -1 << endl;
        return 0;
    }

    int colon1 = -1, colon2 = -1;
    for (int i = left; i <= right; i++) {
        if (s[i] == ':') {
            colon1 = i;
            break;
        }
    }

    for (int i = right; i >= left; i--) {
        if (s[i] == ':') {
            colon2 = i;
            break;
        }
    }

    if (colon1 == -1 || colon2 == -1 || colon1 >= colon2) {
        cout << -1 << endl;
        return 0;
    }

    int count = 4;
    for (int i = colon1 + 1; i < colon2; i++) {
        if (s[i] == '|') {
            count++;
        }
    }

    cout << count << endl;

    return 0;
}

#include <iostream>
using namespace std;

int sumOfDigits(long long n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

int main() {
    long long x;
    cin >> x;

    long long maxSum = 0;
    long long result = 0;

    for (long long i = x; i >= max(1LL, x - 100); i--) {
        if (sumOfDigits(i) > maxSum) {
            maxSum = sumOfDigits(i);
            result = i;
        }
    }

    cout << result << endl;

    return 0;
}

