#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int t;
    cin >> t;

    while (t--) {
        int n, x;
        cin >> n >> x;

        vector<pair<int, int>> blows(n);
        for (int i = 0; i < n; i++) {
            cin >> blows[i].first >> blows[i].second;
        }

        sort(blows.begin(), blows.end());

        int minBlows = 0;
        int curHeads = x;
        for (int i = 0; i < n; i++) {
            int d = blows[i].first;
            int h = blows[i].second;

            while (curHeads > d) {
                minBlows++;
                curHeads = curHeads - d + h;
            }

            if (curHeads <= 0) {
                break;
            }
        }

        if (curHeads <= 0) {
            cout << minBlows << endl;
        } else {
            cout << -1 << endl;
        }
    }

    return 0;
}

