using namespace std;

int main() {
    int n;
    cin >> n;
    string trophies;
    cin >> trophies;

    int maxBeauty = 0;
    int currentBeauty = 0;
    int goldenCount = 0;
    vector<int> goldenIndices;

    for (int i = 0; i < n; i++) {
        if (trophies[i] == 'G') {
            goldenCount++;
            goldenIndices.push_back(i);
        }
    }

    if (goldenCount == 0 || goldenCount == n) {
        cout << goldenCount << endl;
    } else {
        for (int i = 0; i < goldenCount - 1; i++) {
            currentBeauty = goldenIndices[i + 1] - goldenIndices[i] - 1;
            maxBeauty = max(maxBeauty, currentBeauty);
        }

        if (goldenCount < n) {
            currentBeauty = n - goldenIndices[0] - 1;
            maxBeauty = max(maxBeauty, currentBeauty);
            currentBeauty = goldenIndices[0] + 1;
            maxBeauty = max(maxBeauty, currentBeauty);
        }

        cout << maxBeauty << endl;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> p(k);
    set<int> s;
    for (int i = 0; i < k; i++) {
        cin >> p[i];
        s.insert(p[i]);
    }

    vector<int> ans;
    stack<int> st;
    int curr = n;

    for (int i = k - 1; i >= 0; i--) {
        ans.push_back(p[i]);
        while (!st.empty() && st.top() == curr) {
            ans.push_back(st.top());
            st.pop();
            curr--;
        }
        if (p[i] != curr) {
            st.push(p[i]);
        }
    }

    for (int i = curr; i >= 1; i--) {
        if (s.find(i) == s.end()) {
            ans.push_back(i);
        }
    }

    if (ans.size() != n) {
        cout << -1 << endl;
    } else {
        for (int num : ans) {
            cout << num << " ";
        }
        cout << endl;
    }

    return 0;
}

