int main() {
    std::string time;
    std::cin >> time;

    int hh = std::stoi(time.substr(0, 2));
    int mm = std::stoi(time.substr(3, 2));

    int totalMinutes = hh * 60 + mm;

    while (true) {
        totalMinutes = (totalMinutes + 1) % (24 * 60);
        hh = totalMinutes / 60;
        mm = totalMinutes % 60;

        if (isPalindrome(std::to_string(hh / 10) + std::to_string(hh % 10) + ":" + std::to_string(mm / 10) + std::to_string(mm % 10))) {
            std::cout << (totalMinutes - (std::stoi(time.substr(0, 2)) * 60 + std::stoi(time.substr(3, 2)))) << std::endl;
            break;
        }
    }

    return 0;
}

#include <iostream>
