using namespace std;

bool isSymmetric(char a, char b) {
    if ((a == 'b' && b == 'd') || (a == 'd' && b == 'b') || (a == 'p' && b == 'q') || (a == 'q' && b == 'p') || (a == 'o' && b == 'o') || (a == 'v' && b == 'v') || (a == 'w' && b == 'w') || (a == 'x' && b == 'x') || (a == 'A' && b == 'A') || (a == 'H' && b == 'H') || (a == 'I' && b == 'I') || (a == 'M' && b == 'M') || (a == 'O' && b == 'O') || (a == 'T' && b == 'T') || (a == 'U' && b == 'U') || (a == 'V' && b == 'V') || (a == 'W' && b == 'W') || (a == 'X' && b == 'X') || (a == 'Y' && b == 'Y')) {
        return true;
    }
    return false;
}

int main() {
    string s;
    cin >> s;

    int n = s.length();
    bool isPalindrome = true;
    for (int i = 0; i < n / 2; i++) {
        if (!isSymmetric(s[i], s[n - i - 1])) {
            isPalindrome = false;
            break;
        }
    }

    if (isPalindrome) {
        cout << "TAK" << endl;
    } else {
        cout << "NIE" << endl;
    }

    return 0;
}

