bool checkWin(vector<string>& board, int row, int col, int dx, int dy) {
    int count = 0;
    while (row >= 0 && row < 10 && col >= 0 && col < 10 && board[row][col] == 'X') {
        count++;
        row += dx;
        col += dy;
    }
    return count >= 5;
}

bool canWin(vector<string>& board) {
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            if (board[i][j] == '.') {
                if (checkWin(board, i, j, 1, 0) || checkWin(board, i, j, 0, 1) ||
                    checkWin(board, i, j, 1, 1) || checkWin(board, i, j, 1, -1)) {
                    return true;
                }
            }
        }
    }
    return false;
}

int main() {
    vector<string> board(10);
    for (int i = 0; i < 10; i++) {
        cin >> board[i];
    }

    if (canWin(board)) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

