#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;

    std::vector<int> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    std::vector<int> dist(n);
    int nearest_zero = -n;
    for (int i = 0; i < n; i++) {
        if (a[i] == 0) {
            nearest_zero = i;
        }
        dist[i] = i - nearest_zero;
    }

    nearest_zero = 2 * n;
    for (int i = n - 1; i >= 0; i--) {
        if (a[i] == 0) {
            nearest_zero = i;
        }
        dist[i] = std::min(dist[i], nearest_zero - i);
    }

    for (int i = 0; i < n; i++) {
        std::cout << dist[i] << " ";
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    long long d, k, a, b, t;
    cin >> d >> k >> a >> b >> t;

    long long time = 0;
    if (d <= k) {
        time = d * a;
    } else {
        long long fullSegments = d / k;
        long long remainingDistance = d % k;

        time = fullSegments * (k * a + t) + min(remainingDistance * a, t + remainingDistance * b);
    }

    cout << time << endl;

    return 0;
}

