#include <cmath>

using namespace std;

int convertToDecimal(vector<int>& num, int base) {
    int result = 0;
    int power = 0;
    for (int i = num.size() - 1; i >= 0; i--) {
        result += num[i] * pow(base, power);
        power++;
    }
    return result;
}

