int countYearsWithOneZero(long long a, long long b) {
    int count = 0;
    for (long long i = a; i <= b; i++) {
        int numZeros = 0;
        long long num = i;
        while (num > 0) {
            if (num % 2 == 0) {
                numZeros++;
            }
            num /= 2;
        }
        if (numZeros == 1) {
            count++;
        }
    }
    return count;
