int main() {
    long long n, m, x, y, vx, vy;
    cin >> n >> m >> x >> y >> vx >> vy;

    long long dx = (vx > 0) ? n - x : x;
    long long dy = (vy > 0) ? m - y : y;

    long long steps_x = (vx == 0) ? 1e18 : (dx / abs(vx));
    long long steps_y = (vy == 0) ? 1e18 : (dy / abs(vy));

    long long steps = min(steps_x, steps_y);

    if (steps_x < steps_y) {
        x += steps * vx;
        y += steps * vy;
    } else {
        x += steps_x * vx;
        y += steps_y * vy;
    }

    if (x == 0 || x == n) {
        vx *= -1;
    }
    if (y == 0 || y == m) {
        vy *= -1;
    }

    if (x == 0 && y == 0) {
        cout << "0 0" << endl;
    } else if (x == n && y == 0) {
        cout << n << " 0" << endl;
    } else if (x == 0 && y == m) {
        cout << "0 " << m << endl;
    } else if (x == n && y == m) {
        cout << n << " " << m << endl;
