    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> cells[i][j];
        }
    }

    int minBlack = INT_MAX;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (cells[i][j] == 'B') {
                int maxSide = min(n - i, m - j);
                for (int side = 1; side <= maxSide; side++) {
                    bool valid = true;
                    for (int x = i; x < i + side; x++) {
                        for (int y = j; y < j + side; y++) {
                            if (cells[x][y] != 'B') {
                                valid = false;
                                break;
                            }
                        }
                        if (!valid) {
                            break;
                        }
                    }
                    if (valid) {
                        minBlack = min(minBlack, (side * side) - (side * side - (side - 2) * (side - 2)));
                    }
                }
            }
        }
    }

    if (minBlack == INT_MAX) {
        cout << -1 << endl;
    } else {
        cout << minBlack << endl;
    }

    return 0;
}

