#include <iostream>
#include <vector>
#include <unordered_map>
#include <queue>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<vector<int>> adj(n + 1);
    vector<int> in_degree(n + 1, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        in_degree[v]++;
    }

    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (in_degree[i] == 0) {
            count++;
        }
    }

    if (count <= 1) {
        cout << "YES" << endl;
    } else {
        bool acyclic = false;
        for (int i = 1; i <= n; i++) {
            if (in_degree[i] == 1) {
                in_degree[i] = 0;
                queue<int> q;
                vector<bool> visited(n + 1, false);
                q.push(i);
                visited[i] = true;

                while (!q.empty()) {
                    int curr = q.front();
                    q.pop();

                    for (int neighbor : adj[curr]) {
                        in_degree[neighbor]--;
                        if (in_degree[neighbor] == 0) {
                            q.push(neighbor);
                            visited[neighbor] = true;
                        }
                    }
                }

                int reachable = 0;
                for (int j = 1; j <= n; j++) {
                    if (visited[j]) {
                        reachable++;
                    }
                }

                if (reachable == n) {
                    acyclic = true;
                    break;
                }

                in_degree[i] = 1;
            }
        }

        if (acyclic) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
    }

    return 0;
}

