#include <iostream>
#define MOD 1000000007
using namespace std;

int main() {
    int n, x, pos;
    cin >> n >> x >> pos;

    int left = 0, right = n;
    long long ans = 1;
    int less = x - 1, greater = n - x;

    while(left < right) {
        int middle = (left + right) / 2;
        if(middle <= pos) {
            if(middle != pos) {
                ans = (ans * less) % MOD;
                less--;
            }
            left = middle + 1;
        } else {
            ans = (ans * greater) % MOD;
            greater--;
            right = middle;
        }
    }

    for(int i = 1; i <= less + greater; i++) {
        ans = (ans * i) % MOD;
    }

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <string>

using namespace std;

int main() {
    string s;
    cin >> s;
    int k;
    cin >> k;

    string result = "";
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s[i] == '?') {
            if (count < k) {
                result += s[i - 1];
                count++;
            }
        } else if (s[i] == '*') {
            if (count < k) {
                result += s[i - 1];
                count++;
                while (count < k) {
                    result += s[i - 1];
                    count++;
                }
            }
        } else {
            result += s[i];
            count++;
        }
    }

    if (count == k) {
        cout << result << endl;
    } else {
        cout << "Impossible" << endl;
    }

    return 0;
}

